#[inline(always)]
unsafe extern "C" fn FindMatchLengthWithLimit(
    mut s1: *const uint8_t,
    mut s2: *const uint8_t,
    mut limit: size_t,
) -> size_t {
    let s1_orig: *const uint8_t = s1;

    while limit >= 8 as size_t {
        let x: uint64_t =
            BrotliUnalignedRead64(s2 as *const c_void) ^ BrotliUnalignedRead64(s1 as *const c_void);
        if x != 0 as uint64_t {
            let matching_bits: size_t =
                (x as c_ulonglong).trailing_zeros() as i32 as size_t;
            return (s1.offset_from(s1_orig) as c_long as size_t)
                .wrapping_add(matching_bits >> 3 as c_int);
        }
        // SAFETY: The caller guarantees that `s1` and `s2` are valid to read up to `limit`
        // bytes; in this branch `limit >= 8`, so advancing both pointers by 8 stays within
        // the same valid compared range.
        s1 = unsafe { s1.add(8) };
        // SAFETY: Same precondition as above; advancing by 8 is within the remaining `limit`.
        s2 = unsafe { s2.add(8) };
        limit = limit.wrapping_sub(8 as size_t);
    }

    while limit != 0 {
        // SAFETY: The loop invariant maintains that both pointers are valid for at least one
        // byte while `limit != 0`, so dereferencing each pointer is valid.
        if unsafe { *s1 } != unsafe { *s2 } {
            break;
        }
        limit = limit.wrapping_sub(1);
        // SAFETY: After consuming one compared byte, advancing by 1 remains within the valid
        // range tracked by `limit`.
        s1 = unsafe { s1.add(1) };
        // SAFETY: Same as for `s1`; advancing by 1 stays within the valid compared range.
        s2 = unsafe { s2.add(1) };
    }

    s1.offset_from(s1_orig) as c_long as size_t
}

